ON CONFLICT (chart, account_number) DO NOTHING;
-- Databases that ran the first version of 0045 (unreleased) carry the not-yet-due VAT defaults on 1765/1760 (SKR03)
-- and 3815/3810 (SKR04). 1765 and 3815 are reserved in DATEV, 1760/3810 are the accounts without a rate. Move such
-- rows to 1766/1761 and 3816/3811 unless the tenant already booked on the old account (one balance, one account).
UPDATE accounting_account_mappings AS m
SET account_number = fix.new_account, updated_at = CURRENT_TIMESTAMP::text
FROM (VALUES
  ('SKR03', 'output_vat_deferred', '1765', '1766'),
  ('SKR03', 'output_vat_deferred_7', '1760', '1761'),
  ('SKR04', 'output_vat_deferred', '3815', '3816'),
  ('SKR04', 'output_vat_deferred_7', '3810', '3811')
) AS fix(chart, role, old_account, new_account)
WHERE m.chart = fix.chart AND m.role = fix.role AND m.account_number = fix.old_account
  AND NOT EXISTS (
    SELECT 1 FROM journal_lines jl JOIN journal_entries je ON je.tenant_id = jl.tenant_id AND je.id = jl.entry_id
    WHERE jl.tenant_id = m.tenant_id AND jl.account_number = m.account_number AND je.source_type IN ('outgoing_invoice', 'payment_vat')
  );
UPDATE ledger_accounts AS target SET name = fix.name, updated_at = CURRENT_TIMESTAMP::text
FROM (VALUES
  ('SKR03', '0005', 'Rückständige fällige Einzahlungen auf Geschäftsanteile'),
  ('SKR03', '0010', 'Entgeltlich erworbene Konzessionen, gewerbliche Schutzrechte und ähnliche Rechte und Werte sowie Lizenzen an solchen Rechten und Werten'),
  ('SKR03', '0015', 'Konzessionen'),
  ('SKR03', '0020', 'Gewerbliche Schutzrechte'),
  ('SKR03', '0025', 'Ähnliche Rechte und Werte'),
  ('SKR03', '0027', 'EDV-Software'),
  ('SKR03', '0030', 'Lizenzen an gewerblichen Schutzrechten und ähnlichen Rechten und Werten'),
  ('SKR03', '0035', 'Geschäfts- oder Firmenwert'),
  ('SKR03', '0038', 'Anzahlungen auf Geschäfts- oder Firmenwert'),
  ('SKR03', '0039', 'Geleistete Anzahlungen auf immaterielle Vermögensgegenstände'),
