-- Accounts per tenant: an own account (a number the catalogue does not have) or a catalogue account the tenant
-- switched off (active = false). New postings, drafts and mappings only take accounts that are active for the tenant.
CREATE TABLE IF NOT EXISTS tenant_ledger_accounts (
  tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  chart TEXT NOT NULL,
  account_number TEXT NOT NULL,
  name TEXT NOT NULL,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (tenant_id, chart, account_number)
);
